import{_ as o,c as t,o as r,b2 as d}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"操作日志 Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-05-16-operlog.md","filePath":"superpowers/plans/2026-05-16-operlog.md"}'),c={name:"superpowers/plans/2026-05-16-operlog.md"};function a(i,e,l,s,p,n){return r(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="操作日志-implementation-plan" tabindex="-1">操作日志 Implementation Plan <a class="header-anchor vp-link" href="#操作日志-implementation-plan" aria-label="Permalink to &quot;操作日志 Implementation Plan&quot;">​</a></h1><blockquote><p><strong>For agentic workers:</strong> REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (<code>- [ ]</code>) syntax for tracking.</p></blockquote><p><strong>Goal:</strong> 在 quickboot2 中落地操作日志：宽切面 + 事件 + <code>IgnoreLogger</code> 采集写入 <code>sys_oper_log</code>（含 <code>trace_id</code>），并提供 <code>/monitor/operlog</code> 管理端与 quick-ui 页面（列表/详情/删/清空/导出）。</p><p><strong>Architecture:</strong> Controller 方法被 <code>LoggingAspect</code> 等价物环绕，在 <code>finally</code> 中发布携带 <code>traceId</code> 与参数/结果/异常的事件；监听器同步脱敏后写库；管理接口独立模块，<code>POST</code> 表达删除/清空，导出带行数上限。</p><p><strong>Tech stack:</strong> Spring Boot 3、MyBatis-Plus、Sa-Token、Flyway、Micrometer MDC + <code>TraceIds</code>、现有 <code>common.desensitization</code>（或薄封装）、EasyExcel（若项目导出已统一则复用）、Vue 3 + Element Plus。</p><p><strong>设计真源：</strong> <code>docs/superpowers/specs/2026-05-16-operlog-design.md</code></p><hr><h2 id="文件结构-预期" tabindex="-1">文件结构（预期） <a class="header-anchor vp-link" href="#文件结构-预期" aria-label="Permalink to &quot;文件结构（预期）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>区域</th><th>路径/职责</th></tr></thead><tbody><tr><td>Flyway</td><td><code>quickboot-web/src/main/resources/db/migration/V15__sys_oper_log.sql</code>（版本号以仓库当前最大 V 为准顺延）</td></tr><tr><td>菜单种子</td><td>同上文件末尾或 <code>V16__sys_oper_log_menu.sql</code>（<code>menu_id</code> 与 <code>logininfor</code> 等错开）</td></tr><tr><td>切面/注解/事件</td><td><code>quickboot-common</code> 或 <code>quickboot-web</code> 下独立包，如 <code>...common.monitor.operlog</code>（与自动配置同模块，避免 web 依赖环）</td></tr><tr><td>监控业务</td><td><code>quickboot-web/.../monitor/operlog/</code> Controller、Service、Mapper、Entity、Bo、Vo</td></tr><tr><td>前端</td><td><code>quick-ui/src/api/monitor/operlog.ts</code>、<code>views/monitor/operlog/</code>、路由与权限常量</td></tr></tbody></table></div><p>实现前通读：<code>openspec/project.md</code>、<code>sdd/后端代码规范.md</code>、<code>sdd/前端代码规范.md</code>、<code>sdd/数据库设计规范.md</code>、<code>DESIGN.md</code>（前端）。</p><hr><h3 id="task-1-数据库与实体" tabindex="-1">Task 1: 数据库与实体 <a class="header-anchor vp-link" href="#task-1-数据库与实体" aria-label="Permalink to &quot;Task 1: 数据库与实体&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>quickboot-web/src/main/resources/db/migration/Vn__sys_oper_log.sql</code>（<code>n</code> = 当前最大 + 1）</p></li><li><p>Create: Entity / Mapper 接口（MyBatis-Plus）</p></li><li><p>[ ] <strong>Step 1:</strong> 按设计文档建 <code>sys_oper_log</code>（若依列 + <code>trace_id</code> VARCHAR + <code>idx</code> on <code>oper_time</code>、<code>trace_id</code> 等）</p></li><li><p>[ ] <strong>Step 2:</strong> 实体主键 <code>BIGINT</code> 与现有 <code>sys_dept</code> 等一致；字段 JavaDoc 中文</p></li><li><p>[ ] <strong>Step 3:</strong> <code>mvn -pl quickboot-web -am test</code> 或至少编译通过</p></li></ul><hr><h3 id="task-2-ignorelogger-事件-dto-切面" tabindex="-1">Task 2: <code>@IgnoreLogger</code> + 事件 DTO + 切面 <a class="header-anchor vp-link" href="#task-2-ignorelogger-事件-dto-切面" aria-label="Permalink to &quot;Task 2: `@IgnoreLogger` + 事件 DTO + 切面&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: 注解 <code>IgnoreLogger</code>（<code>ALL</code>/<code>PARAMS</code>/<code>RESULT</code>）</p></li><li><p>Create: <code>OperLogEvent</code> / <code>OperLogEventPayload</code>（含 <code>traceId</code>、<code>signature</code>、<code>args</code>、<code>result</code>、<code>throwable</code>、时间戳）</p></li><li><p>Create: <code>OperLogPublishingAspect</code>（<code>@Around</code> 切点与旧 <code>LoggingAspect</code> 等价验证）</p></li><li><p>Modify: 某 <code>*AutoConfiguration</code> 或 <code>WebMvc</code> 配置类注册切面 Bean</p></li><li><p>[ ] <strong>Step 1:</strong> 切面 <code>finally</code> 中设置 <code>payload.traceId = TraceIds.current()</code>（字符串可空）</p></li><li><p>[ ] <strong>Step 2:</strong> 单元测试：带 MDC 时 payload 含 traceId；<code>@IgnoreLogger(ALL)</code> 不发布事件</p></li></ul><hr><h3 id="task-3-监听器落库-脱敏-状态映射" tabindex="-1">Task 3: 监听器落库 + 脱敏 + 状态映射 <a class="header-anchor vp-link" href="#task-3-监听器落库-脱敏-状态映射" aria-label="Permalink to &quot;Task 3: 监听器落库 + 脱敏 + 状态映射&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>OperLogPersistListener</code>（<code>@EventListener</code> 同步）</p></li><li><p>Create: <code>OperLogAssembler</code>（DTO → Entity：<code>status</code> 0/1、异常填 <code>error_msg</code>、方法名缩短等）</p></li><li><p>Create/Modify: <code>OperLogSensitiveMasker</code> 调用现有 <code>common.desensitization</code> 能力或键名黑名单</p></li><li><p>[ ] <strong>Step 1:</strong> 写库失败 catch 打日志，不抛出不阻断</p></li><li><p>[ ] <strong>Step 2:</strong> 集成测试或 <code>@SpringBootTest</code> 最小用例：发布事件后表中有行且 <code>trace_id</code> 正确</p></li></ul><hr><h3 id="task-4-operlogmeta-与-openapi-兜底" tabindex="-1">Task 4: <code>@OperLogMeta</code> 与 OpenAPI 兜底 <a class="header-anchor vp-link" href="#task-4-operlogmeta-与-openapi-兜底" aria-label="Permalink to &quot;Task 4: `@OperLogMeta` 与 OpenAPI 兜底&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: 可选注解 <code>OperLogMeta</code>（<code>title</code>、<code>businessType</code> 等）</p></li><li><p>Create: 从 <code>HandlerMethod</code> 读 <code>@Tag</code>/<code>@Operation</code> 的解析器（无 Swagger 依赖则用 Springdoc 等价元数据）</p></li><li><p>[ ] <strong>Step 1:</strong> 无注解时有合理默认标题；有 <code>@OperLogMeta</code> 时覆盖</p></li></ul><hr><h3 id="task-5-管理端-api" tabindex="-1">Task 5: 管理端 API <a class="header-anchor vp-link" href="#task-5-管理端-api" aria-label="Permalink to &quot;Task 5: 管理端 API&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>...monitor/operlog/*Controller</code>、Service、Mapper XML（若需）、Bo、Vo</p></li><li><p>Modify: <code>application.yml</code> 增加 <code>qc.monitor.operlog.export-max-rows</code>（默认 10000）</p></li><li><p>[ ] <strong>Step 1:</strong> <code>GET /list</code>、<code>GET /{id}</code>、<code>POST /remove</code>、<code>POST /clean</code>、<code>POST /export</code> + 权限注解</p></li><li><p>[ ] <strong>Step 2:</strong> Controller 类或方法加 <code>@IgnoreLogger(ALL)</code></p></li><li><p>[ ] <strong>Step 3:</strong> 导出超限时业务异常（项目自定义异常）</p></li></ul><hr><h3 id="task-6-路径排除配置" tabindex="-1">Task 6: 路径排除配置 <a class="header-anchor vp-link" href="#task-6-路径排除配置" aria-label="Permalink to &quot;Task 6: 路径排除配置&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>OperLogProperties</code>（<code>ignore-url-patterns</code> 列表默认值）</p></li><li><p>[ ] <strong>Step 1:</strong> 切面内对匹配 URL 直接 return，不发布事件</p></li></ul><hr><h3 id="task-7-菜单与字典" tabindex="-1">Task 7: 菜单与字典 <a class="header-anchor vp-link" href="#task-7-菜单与字典" aria-label="Permalink to &quot;Task 7: 菜单与字典&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Modify: Flyway 插入 <code>sys_menu</code>、<code>sys_role_menu</code>；字典 <code>sys_dict_data</code> 若业务类型等缺失则种子补齐</p></li><li><p>[ ] <strong>Step 2:</strong> 与需求权限字符串 <code>monitor:operlog:*</code> 一致</p></li></ul><hr><h3 id="task-8-前端" tabindex="-1">Task 8: 前端 <a class="header-anchor vp-link" href="#task-8-前端" aria-label="Permalink to &quot;Task 8: 前端&quot;">​</a></h3><p><strong>Files:</strong></p><ul><li><p>Create: <code>quick-ui/src/api/monitor/operlog.ts</code></p></li><li><p>Create: <code>views/monitor/operlog/index.vue</code>（及详情组件）</p></li><li><p>Modify: 路由、国际化键（若项目使用）</p></li><li><p>[ ] <strong>Step 1:</strong> <code>pnpm build:prod</code> 通过</p></li></ul><hr><h3 id="task-9-全链路自测清单" tabindex="-1">Task 9: 全链路自测清单 <a class="header-anchor vp-link" href="#task-9-全链路自测清单" aria-label="Permalink to &quot;Task 9: 全链路自测清单&quot;">​</a></h3><ul><li>[ ] 任意已登录业务请求产生一条 <code>sys_oper_log</code>，<code>trace_id</code> 与 <code>R</code> 或日志一致</li><li>[ ] 列表筛选、<code>trace_id</code> 精确查询、排序、详情、删除、清空、导出</li><li>[ ] <code>/monitor/operlog/list</code> 不产生爆炸性自记日志</li></ul><hr><p><strong>备注：</strong> 实现时若发现与 <code>logininfor</code> 包结构或 Flyway 序号冲突，以仓库当时状态顺延版本号与 <code>menu_id</code>，并在 PR 说明中列出。</p>',47)])])}const h=o(c,[["render",a]]);export{u as __pageData,h as default};
